const r = $input.first().json;
if (Number(r.statusCode) < 200 || Number(r.statusCode) >= 300) throw new Error('Geracao JWT nao retornou sucesso HTTP.');
let b = r.body ?? r.data;
for (let i=0;i<2;i++) { if (typeof b !== 'string') break; try { b=JSON.parse(b); } catch { break; } }
const token = typeof b === 'string' ? b.trim() : b?.token ?? b?.Token ?? b?.access_token;
if (typeof token !== 'string' || !/^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(token)) throw new Error('Resposta sem JWT reconhecivel. Conferir formato oficial sem compartilhar token.');
return [{json:{token}}];
